+void SecretAgent::showWrongPasswordNotification(const QSharedPointer<SecretsRequest> &request)
+{
+    auto notification = new KNotification(QStringLiteral("FailedToGetSecrets"), KNotification::Persistent);
+    notification->setComponentName(QStringLiteral("networkmanagement"));
+    notification->setIconName(QStringLiteral("dialog-password"));
+    notification->setTitle(request->connection.value(QStringLiteral("connection")).value(QStringLiteral("id")).toString());
+    notification->setText(i18n("Could not connect to this network. The password may be wrong or may have changed."));
+
+    const auto weakRequest = request.toWeakRef();
+    auto enterPasswordAction = notification->addAction(i18nc("@action:button", "Enter Password…"));
+    connect(enterPasswordAction, &KNotificationAction::activated, this, [this, weakRequest, path = request->connection_path.path()]() {
+        auto request = weakRequest.toStrongRef();
+        if (request) {
+            request->notificationActivated = true;
+            processNext();
+        } else {
+            // NetworkManager no longer waits for this answer; connecting again makes it ask for the new password
+            NetworkManager::activateConnection(path, QString(), QString());
+        }
+    });
+    connect(notification, &KNotification::closed, this, [this, weakRequest]() {
+        auto request = weakRequest.toStrongRef();
+        if (request && !request->notificationActivated && m_calls.removeOne(request)) {
+            sendError(SecretAgent::UserCanceled, QStringLiteral("User closed the wrong password notification"), request->message);
+            processNext();
+        }
+    });
+    // NetworkManager gives up on secret requests after two minutes without telling the agent
+    QTimer::singleShot(std::chrono::minutes(2), this, [this, weakRequest]() {
+        auto request = weakRequest.toStrongRef();
+        if (request && !request->notificationActivated) {
+            m_calls.removeOne(request);
+        }
+    });
+
+    request->notification = notification;
+    notification->sendEvent();
+}
